-- #987 wave 1 (pure additions): Southern Barrens creature abilities, imported from DeltaTho PR 15 file 2026_10_24_39_world.sql.
-- 85 creatures, 185 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '3245,3246,3248,3253,3376,3425,3426,3454,3455,4127,5848,5851,5863,5864,34640,37082,37083,37084,37085,37086,37088,37092,37093,37157,37159,37160,37161,37165,37170,37180,37204,37206,37207,37208,37216,37220,37511,37513,37553,37555,37556,37557,37559,37560,37585,37660,37661,37706,37743,37922,37923,37924,37925,37940,38033,38070,38290,38327,38333,38384,38385,38624,38636,38658,38659,38661,38663,38826,38875,38884,38940,38941,39136,39153,39156,39174,39220,39279,39280,39281,51851,51852,51853,51859,51861';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
